       "code": "public static bool ExistsInBST(BinNode<int> bt, int Value)\n{\n    while (bt != null)\n    {\n        if (bt.GetValue() == Value)\n            return true;\n        if (bt.GetValue() > Value)\n            bt = bt.GetLeft();\n        else\n            bt = bt.GetRight();\n    }\n    return false;\n}",
       "origin": "teacher-enrichment"
